// Written-test question bank, FAA IRA style (3-option multiple choice).
//
// Correctness rules:
// - Every entry-determination answer is generated by `determineEntry` — the
//   engine is the oracle; no hand-keyed entry answers exist in this file.
//   Dual-keyed options ("Parallel or teardrop") appear exactly when the engine
//   reports a near-boundary heading (±5°, AIM 5-3-8 j8).
// - Every fact carries a `source` citing the FAA primary source. Aviation
//   facts were verified against faa.gov/eCFR text during implementation:
//   AIM 5-3-8 (speeds, timing, DME legs, entries), AIM 5-3-3 a1(f)/(g)
//   (holding reports), 14 CFR 91.185(c) (lost comm), FAA-S-ACS-8C Task III.B.
// - Chart-derived holds come from the current dTPP plates cross-checked
//   against the same-cycle CIFP ARINC 424 HM/HF records.

import {
  determineEntry,
  ENTRIES,
  type Entry,
  type EntryResult,
  type TurnDirection,
} from '../engine/entry'
import { radialToInboundCourse } from '../engine/geometry'
import type { LegSpec } from '../engine/clearance'

export type Topic = 'entry' | 'speeds' | 'timing' | 'reports' | 'lost-comm' | 'pattern' | 'chart'

export const TOPICS: readonly Topic[] = [
  'entry',
  'speeds',
  'timing',
  'reports',
  'lost-comm',
  'pattern',
  'chart',
]

export interface EntryScenario {
  /** Aircraft heading approaching the fix, degrees magnetic. */
  heading: number
  /** Inbound holding course TO the fix, degrees magnetic. */
  inboundCourse: number
  turnDirection: TurnDirection
}

export interface WrittenQuestion {
  id: string
  topic: Topic
  question: string
  options: readonly string[]
  answerIndex: number
  explanation: string
  source: string
  /** ACS element code (FAA-S-ACS-8C, Task III.B). */
  acs: string
  /** Present on entry questions; lets tests re-derive the key from the engine. */
  entry?: EntryScenario
}

