// --- entry questions: options and key generated by the engine ---------------

const ENTRY_LABELS: Record<Entry, string> = {
  direct: 'Direct',
  teardrop: 'Teardrop',
  parallel: 'Parallel',
}

/** Literal written-test option formats for near-boundary questions. */
const PAIR_OPTIONS: readonly string[] = [
  'Direct or teardrop',
  'Direct or parallel',
  'Teardrop or parallel',
]

/** Builds the option list and key for an engine result — exported for tests. */
export function entryOptionSet(result: EntryResult): {
  options: readonly string[]
  answerIndex: number
} {
  if (result.alternates.length === 0) {
    return {
      options: ENTRIES.map((e) => ENTRY_LABELS[e]),
      answerIndex: ENTRIES.indexOf(result.primary),
    }
  }
  const acceptable = ENTRIES.filter(
    (e) => e === result.primary || result.alternates.includes(e),
  )
  if (acceptable.length !== 2) {
    throw new Error(`expected exactly 2 acceptable entries, got ${acceptable.join(', ')}`)
  }
  const label = `${ENTRY_LABELS[acceptable[0]!]} or ${ENTRY_LABELS[acceptable[1]!].toLowerCase()}`
  const answerIndex = PAIR_OPTIONS.indexOf(label)
  if (answerIndex === -1) {
    throw new Error(`no pair option matches ${label}`)
  }
  return { options: PAIR_OPTIONS, answerIndex }
}

/** Aviation course readout: three digits, 0 shown as 360. */
function course3(deg: number): string {
  const d = Math.round(deg) === 0 ? 360 : Math.round(deg)
  return `${String(d).padStart(3, '0')}°`
}

interface EntrySpec {
  id: string
  scenario: EntryScenario
  question: string
  source: string
  acs: string
}

function entryExplanation(scenario: EntryScenario, result: EntryResult): string {
  const base =
    `Sectors per AIM 5-3-8 j3: direct 180°, teardrop 70°, parallel 110°, split by the ` +
    `70° line on the holding side. Against the ${course3(scenario.inboundCourse)} inbound ` +
    `course with ${scenario.turnDirection} turns, heading ${course3(scenario.heading)} falls ` +
    `in the ${result.primary} sector.`
  if (result.alternates.length === 0) {
    return base
  }
  const alt = result.alternates.map((a) => ENTRY_LABELS[a].toLowerCase()).join(' or ')
  return (
    base +
    ` The heading lies within 5° of the sector boundary — AIM 5-3-8 j8(d) treats ±5° in ` +
    `heading as within good operating limits for determining entry — so ${alt} is equally ` +
    `acceptable; written questions key this case as a combined answer.`
  )
}

function buildEntryQuestion(spec: EntrySpec): WrittenQuestion {
  const result = determineEntry(spec.scenario.heading, spec.scenario)
  const { options, answerIndex } = entryOptionSet(result)
  return {
    id: spec.id,
    topic: 'entry',
    question: spec.question,
    options,
    answerIndex,
    explanation: entryExplanation(spec.scenario, result),
    source: spec.source,
    acs: spec.acs,
    entry: spec.scenario,
  }
}

